-- =============================================================================
-- Eden Apothecary: pre-1900 energetics sources for 25 more herbs (research
-- batch 5). DATA ONLY. Written 2026-09-15.
-- =============================================================================
-- Approved by the founder on 2026-09-15, as researched.
--
-- Writes public.herbs.energetics_citation for 25 herbs that had NULL
-- (9 where the old sources agree, 5 where they disagree and the page says so,
-- 4 with no pre-1900 source found at all). Same jsonb shape as batches 1 to 4,
-- carrying 'batch': 5.
--
-- This batch changes NO app value: every stored temperature and moisture in it
-- was judged clear, so the July 2026 ruling keeps all of them. Section 3 asserts
-- that nothing moved.
--
-- 7 herbs here found old readings but counted none of them (wrong species,
-- wrong plant part, a group statement, or the writer quoting someone else).
-- Each carries its own plain sentence saying why, free to read, per the founder
-- decision of 2026-09-15 that silence on such a page reads as 'nobody looked':
--   H052 Rose:
--     'No pre-1900 source found for this exact plant. The old books hand the wild rose back to the garden rose, and what they say about the garden rose is either about roses as a group or is quoted from another writer.'
--   H057 Slippery Elm:
--     'No pre-1900 source found for this exact plant. The old books describe the European elm, not the American slippery elm this entry is about.'
--   H061 Usnea:
--     'No pre-1900 source found for this exact plant. The old books speak of tree moss as a group and say its quality changes with the tree it grows on, and the one writer who names Usnea is passing on Galen.'
--   H062 Uva Ursi:
--     'No pre-1900 source found for this exact plant and part. The one old reading is about the whortleberries as a group, and it describes their berries rather than the bearberry leaf.'
--   H066 Wild Yam:
--     'No pre-1900 source found for this exact plant. The one old reading describes the Chinese yam, a different species from the American wild yam this entry is about.'
--   H070 Yellow Dock:
--     'No pre-1900 source found for this exact plant. The old books speak of the docks as a group, or name kinds that are not the curled dock this entry is about.'
--   H075 Anise Hyssop:
--     'No pre-1900 source found for this exact plant. The one old reading describes the Asian huo xiang, a different species from the North American anise hyssop this entry is about.'
--
-- BLAST RADIUS: production data on 25 of 300 herbs in public.herbs, one column,
-- energetics_citation, on rows where it is currently NULL. No temperature or
-- moisture changes, no schema change, no view change, no grant change, no RLS
-- change. The 69 legacy single-source citations and the 100 herbs already carrying
-- a batch object are untouched.
--
-- IDEMPOTENT. Verification aborts the whole transaction on any failure.
-- =============================================================================

begin;

-- -----------------------------------------------------------------------------
-- 0. Snapshot, so section 3 can prove no herb's energetics moved.
-- -----------------------------------------------------------------------------
create temporary table _energetics_before_b5 on commit drop as
  select herb_id, temperature, moisture from public.herbs;

-- -----------------------------------------------------------------------------
-- 1. The researched sources, staged then applied under one guard loop. The guard
--    refuses to overwrite anything that is not NULL and not already a batch
--    object.
-- -----------------------------------------------------------------------------
create temporary table _energetics_batch5 (
  herb_id text primary key,
  citation jsonb not null
) on commit drop;

-- H051 Rhodiola (2 sources, SOURCES DISAGREE)
insert into _energetics_batch5 values ('H051', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Gerard 1633, Book II Chap. 153 'Of Rosewort, or Roseroot': the plant is described at length and is plainly this one, but under The Virtues he writes 'There is little extant in writing of the faculties of Rosewort', and he gives no temperature and no Temperature section at all", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III, Ibn al-Baytar (Leclerc Vols. I and II), Schopf 1787, Rafinesque 1828-30: no Rhodiola entry found"], "counted_readings": {"moisture": [{"reading": "Moist", "source": "Salmon (1710)"}], "temperature": [{"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}]}, "disagreement_text": "On moisture, Salmon (1710) reads it as moist. The app keeps dry, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root. Culpeper lists Rose Root among the ROOTS; Salmon gives one reading for the whole plant and his preparations are made from root, leaves and stalks."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Roots cold in the first degree. Sorrel, Beets, white and red, Comfrey the greater, Plantain, Rose Root, Madder.; and in the same tables, 'Roots cool the head. Rose root.'", "gloss": "Rose Root is listed among the roots cold in the first degree, and among the roots that cool the head.", "locator": "Culpeper's degree tables, 'Roots' (Gutenberg #49513, offset ~935400)", "not_counted_why": "", "note": "Rose Root is Rhodia radix, this plant; Salmon's Latin index gives 'Rhodia radix, Rose Root' for the same chapter. Culpeper names it on its own line, not as part of a group, so it counts. He puts it in none of his dry or moist root tables, so this is a temperature only.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VILL The Qualities. It is cold and moift im the firft Degree, Anodyn, Cephalick, and Neuro- tick.", "gloss": "Rosewort is cold and moist in the first degree.", "locator": "Chapter 'Of ROSE-WORT: OR, ROSE-ROOT', The Qualities (OCR at offset 5072947; the running head on the page reads Chap. 601, while the book's English index lists Rose-wort at 600)", "not_counted_why": "", "note": "Salmon gives the degree himself and names no authority, so it is first-hand. His chapter is Rhodia radix, this plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H052 Rose (4 sources, shown, none counted)
insert into _energetics_batch5 values ('H052', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787), no. 172: the entry is Rosa rubiginosa, the sweet brier, and its qualities are 'fragrans, pallida, spirituosa' with no temperature or moisture", "Watt, Dictionary of the Economic Products of India Vol. IV: the only line is 'Hips, see Rosa canina, Linn.' with the article promised in Vol. VI, which was not available", "Dymock Vols. I-III, Ibn al-Baytar (Leclerc Vols. I and II), Rafinesque 1828-30: no Rosa canina article", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no dog rose entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books hand the wild rose back to the garden rose, and what they say about the garden rose is either about roses as a group or is quoted from another writer.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because readings were found but none of them counts: No pre-1900 source found for this exact plant. The old books hand the wild rose back to the garden rose, and what they say about the garden rose is either about roses as a group or is quoted from another writer.", "The stored plant is Rosa canina, the dog rose or wild brier, and the stored parts are the hip and the petal."], "part_used": "Hip, Petal", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. The cross-reference points at Gerard's own rose chapter, and that chapter's reading is a statement about the whole group: 'all of them have a predominant or overruling cold temperature ... cold in the first degree, moist, airy, and spiritual parts are predominant in the White roses, Damask and Musk' (Book III, Chap. 1 'Of Roses'). A group statement does not count, so a cross-reference that leads to one does not count either.", "assigns_moisture": "Moist", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature and Virtues. A. The faculties of these wild Roses are referred to the manured Rose, but not used in physic where the other may be had", "gloss": "The wild roses are referred to the garden rose for their faculties.", "locator": "Book III, Chap. 3 'Of the Wild Roses', The Temperature and Virtues", "not_counted_why": "The cross-reference points at Gerard's own rose chapter, and that chapter's reading is a statement about the whole group: 'all of them have a predominant or overruling cold temperature ... cold in the first degree, moist, airy, and spiritual parts are predominant in the White roses, Damask and Musk' (Book III, Chap. 1 'Of Roses'). A group statement does not count, so a cross-reference that leads to one does not count either.", "note": "The cross-reference points at Gerard's own rose chapter, and that chapter's reading is a statement about the whole group: 'all of them have a predominant or overruling cold temperature ... cold in the first degree, moist, airy, and spiritual parts are predominant in the White roses, Damask and Musk' (Book III, Chap. 1 'Of Roses'). A group statement does not count, so a cross-reference that leads to one does not count either.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Two reasons not to count it. The comparison is hedged, 'are generally held to come near', which is the same shape as 'is thought to be'. And the drying he describes is an action on the stomach, not a felt quality of the drug.", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "the wild Roses also are few or none of them used in physic, but are generally held to come near the nature of the manured Roses. The fruit of the wild briar, which are called Hips, being thoroughly ripe, and made into a conserve with sugar ... doth gently bind the belly, and stay defluctions from the head upon the stomach, drying up the moisture thereof", "gloss": "The wild roses are generally held to come near the nature of the garden roses; the hips gently bind and dry up the moisture of the stomach.", "locator": "ROSES chapter (Gutenberg #49513, offset ~572838)", "not_counted_why": "Two reasons not to count it. The comparison is hedged, 'are generally held to come near', which is the same shape as 'is thought to be'. And the drying he describes is an action on the stomach, not a felt quality of the drug.", "note": "Two reasons not to count it. The comparison is hedged, 'are generally held to come near', which is the same shape as 'is thought to be'. And the drying he describes is an action on the stomach, not a felt quality of the drug.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. A statement about roses as a group, and the kinds named are the garden roses, not Rosa canina. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Cold in the first degree. Mallows, Roses, red, white, and damask Violets. ... Dry in the first degree. Ox-eye, Saffron, Chamomel, Melilot, Roses.", "gloss": "Roses, red, white and damask, are cold in the first degree and dry in the first degree.", "locator": "Culpeper's degree tables, 'Flowers' (Gutenberg #49513, offset ~963400)", "not_counted_why": "A statement about roses as a group, and the kinds named are the garden roses, not Rosa canina. Shown, not counted.", "note": "A statement about roses as a group, and the kinds named are the garden roses, not Rosa canina. Shown, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. The chapter it points to gives its degree as a report: 'Mesues says, that the Rose ... is cold in the first Degree, and dry in the second' (Chap. DCI, OCR at offset 5103204). A cross-reference cannot count for more than the reading it points at, and that reading is Mesue's, not Salmon's.", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "XVII. As to their Qualities, Specification, Pre- parations and Virtues of thefe Wild Rofes, they are much the fame with thofe of Red Ro/es in the former Chapter, tho? indeed they are feldom or never ufed in Phyfick", "gloss": "The wild roses are much the same in quality as the red roses of the former chapter.", "locator": "Chap. DCII 'Of ROSE Wild; OR, BRIAR-BUSH' (OCR at offset 5153992)", "not_counted_why": "The chapter it points to gives its degree as a report: 'Mesues says, that the Rose ... is cold in the first Degree, and dry in the second' (Chap. DCI, OCR at offset 5103204). A cross-reference cannot count for more than the reading it points at, and that reading is Mesue's, not Salmon's.", "note": "The chapter it points to gives its degree as a report: 'Mesues says, that the Rose ... is cold in the first Degree, and dry in the second' (Chap. DCI, OCR at offset 5103204). A cross-reference cannot count for more than the reading it points at, and that reading is Mesue's, not Salmon's.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H053 Rosemary (4 sources, sources agree)
insert into _energetics_batch5 values ('H053', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Bencao Congxin (1757), Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no rosemary entry found", "Dymock, Pharmacographia Indica Vols. I-III: rosemary appears only in passing and carries no thermal quality"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the leaf. Gerard and Culpeper give the degree for the herb."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Rosemary is hot and dry in the second degree, and also of an astringent or binding quality, as being compounded of divers parts, and taking more of the mixture of the earthy substance.", "gloss": "Rosemary is hot and dry in the second degree.", "locator": "Book III, Chap. 8 'Of Rosemary', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Rosmarirum. Rosemary, hot and dry in the second degree, binding, stops fluxes, helps stuffings in the head, the yellow jaundice, helps the memory, expels wind. See the flowers. Serapio, Dioscorides.; and in his degree tables, Rosemary is listed hot in the second degree and dry in the second degree", "gloss": "Rosemary is hot and dry in the second degree.", "locator": "Catalogue of simples, Herbs, 'Rosmarinum' (Gutenberg #49513, offset ~890329); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The entry ends with the authorities 'Serapio, Dioscorides' in italics. Following the rule you confirmed, a name at the END of an entry is Culpeper's reference and not a report, so this counts. His tables agree with the entry, so he does not vote twice.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. 'are said by Authors' makes this a report of other writers rather than Salmon's own reading, so it is shown and not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "UX. The Qualities. The laft or fourth is fearce- ly ever ufed in Phyfick: the firft three have all of them, the fame Qualities, Virtues, and Operations, and are faid by Authors to be hot and dry in the third Degree", "gloss": "The first three kinds of rosemary are said by authors to be hot and dry in the third degree.", "locator": "Chap. DCIII 'Of ROSEMARY' (OCR at offset 5162165)", "not_counted_why": "'are said by Authors' makes this a report of other writers rather than Salmon's own reading, so it is shown and not counted.", "note": "'are said by Authors' makes this a report of other writers rather than Salmon's own reading, so it is shown and not counted.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Two reasons not to count it. The entry is marked as taken from the Bencao Shiyi of 739, so the reading is quoted from a book that was not read, and Li Xun is quoted against it in the same line. The identification of this drug with Rosmarinus officinalis rests on Li Shizhen's account of a plant brought from Rome, not on a botanical name.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "迷迭香 ... 氣味辛温無毒主治惡氣令人衣香燒之去鬼{{SKnotes|藏器玣曰性平不温}}", "gloss": "Mi die xiang: pungent, WARM, not toxic; against evil airs, it perfumes the clothes, and burnt it drives off ghosts. Li Xun adds: its nature is NEUTRAL, not warm.", "locator": "卷十四 草之三 芳草類, 迷迭香 (bcgm_14.txt offset 53267)", "not_counted_why": "Two reasons not to count it. The entry is marked as taken from the Bencao Shiyi of 739, so the reading is quoted from a book that was not read, and Li Xun is quoted against it in the same line. The identification of this drug with Rosmarinus officinalis rests on Li Shizhen's account of a plant brought from Rome, not on a botanical name.", "note": "Two reasons not to count it. The entry is marked as taken from the Bencao Shiyi of 739, so the reading is quoted from a book that was not read, and Li Xun is quoted against it in the same line. The identification of this drug with Rosmarinus officinalis rests on Li Shizhen's account of a plant brought from Rome, not on a botanical name.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H054 Sage (3 sources, sources agree)
insert into _energetics_batch5 values ('H054', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787): the Salvia entries are American species", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Salvia officinalis entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the leaf; all three English writers give the degree for the herb."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Sage is manifestly hot and dry in the beginning of the third degree, or in the later end of the second; it hath adjoined no little astriction or binding.", "gloss": "Sage is hot and dry at the join of the second and third degrees.", "locator": "Book II, Chap. 266 'Of Sage', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Salvia. Sage: hot and dry in the second or third degree, binding, it stays abortion in such women as are subject to come before their times, it causes fruitfulness, it is singularly good for the brain, strengthens the senses and memory; and in his degree tables, Sage is listed hot in the second degree and dry in the second degree", "gloss": "Sage is hot and dry in the second or third degree.", "locator": "Catalogue of simples, Herbs, 'Salvia' (Gutenberg #49513, offset ~891601); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "No authority is named anywhere in the entry, so it is Culpeper's own.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. 'is said to be' hedges the reading in the same way as 'is thought to be', so it is shown and not counted. His wild sage chapter, which is a different species, says 'They are all of them hot and dry in the second degree' without the hedge.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "IX. The Qualities. Sage is faid to be hot and dry in the third Degree, Aftringent, Anodyn, Car- minative, Digeftive, Difeuffive, Diuretick, and Traumatick", "gloss": "Sage is said to be hot and dry in the third degree.", "locator": "Chap. DCXIV 'Of SAGE GARDEN', The Qualities (OCR at offset 5329000; the chapter opens at offset 5326115)", "not_counted_why": "'is said to be' hedges the reading in the same way as 'is thought to be', so it is shown and not counted. His wild sage chapter, which is a different species, says 'They are all of them hot and dry in the second degree' without the hedge.", "note": "'is said to be' hedges the reading in the same way as 'is thought to be', so it is shown and not counted. His wild sage chapter, which is a different species, says 'They are all of them hot and dry in the second degree' without the hedge.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H055 Schisandra (3 sources, sources agree)
insert into _energetics_batch5 values ('H055', $j${"agreement_state": "agree", "app_value": {"moisture": "Neutral", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Culpeper 1653, Gerard 1633, Salmon 1710: no schisandra chapter (the plant is Chinese and none of the three knew it)", "Porter Smith 1871, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III, Dutt 1877: no Schisandra chinensis entry with a thermal quality"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the berry, which is what all three Chinese books mean by wu wei zi."], "part_used": "Berry", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "五味子 味酸，溫。主益氣，敘逆上氣，勞傷羸瘦。補不足，強陰，益男子精。", "gloss": "Wu wei zi: taste sour, nature WARM. It benefits the qi, treats cough with rebellious qi and wasting from overwork, supplements what is lacking and strengthens the yin.", "locator": "草上品, 五味子 (Sun Xingyan recension, shennong_sun.txt offset 22600)", "not_counted_why": "", "note": "Temperature only; the entry gives no moisture word.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "五味子 補肺腎、濇精氣。性溫。五味俱備。", "gloss": "Wu wei zi: it supplements lung and kidney and astringes the essence. Nature WARM. All five tastes are complete in it.", "locator": "卷五 草部, 五味子 (congxin.txt offset 61581)", "not_counted_why": "", "note": "Wu Yiluo writes his own compressed 'nature warm' rather than copying the Shennong sentence, so it is counted; it agrees with the older reading it descends from. He adds that the best come from the north and are purple-black, which is Schisandra chinensis, the stored plant. Temperature only.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. The heading and the whole indication list are marked as copied from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own discussion only quotes Kou Zongshi's complaint that 'the Bencao Jing says its nature is warm' and gives no fresh degree.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味酸温無毒 ... 主治益氣敘逆上氣勞傷羸瘦補不足強陰益男子精{{SKnotes|本經}}", "gloss": "Qi and flavour: sour, WARM, not toxic. Indications: benefits the qi, cough with rebellious qi, wasting from overwork, supplements what is lacking, strengthens the yin.", "locator": "卷十八上 草之七, 五味子, 氣味 (bcgm_18a.txt offset 3350)", "not_counted_why": "The heading and the whole indication list are marked as copied from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own discussion only quotes Kou Zongshi's complaint that 'the Bencao Jing says its nature is warm' and gives no fresh degree.", "note": "The heading and the whole indication list are marked as copied from the Shennong Bencao Jing, so the reading counts once and is credited to Shennong. Li Shizhen's own discussion only quotes Kou Zongshi's complaint that 'the Bencao Jing says its nature is warm' and gives no fresh degree.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Neutral", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

