-- H057 Slippery Elm (2 sources, shown, none counted)
insert into _energetics_batch5 values ('H057', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Neutral (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787), nos. 76 and 77: no. 77, the 'Salve-Bark', is the slippery elm, and its entry reads 'QVAL. insipida, inodora, mucilaginosa. vis: emolliens, obtundens, consolidans', which is taste and virtue, not a felt temperature or moisture", "Rafinesque, Medical Flora (1828-30): Ulmus fulva is named several times as a discutient and demulcent, with no temperature or moisture", "Salmon 1710: the elm is a tree and falls in Lib. II, which was not read", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Ulmus rubra entry"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books describe the European elm, not the American slippery elm this entry is about.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because readings were found but none of them counts: No pre-1900 source found for this exact plant. The old books describe the European elm, not the American slippery elm this entry is about.", "The stored plant is the American Ulmus rubra and the stored part is the inner bark."], "part_used": "Inner Bark", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral), so it stays Neutral. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Gerard's elm is the European Ulmus, not the American slippery elm. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature and Virtues. A. The leaves and bark of the Elm be moderately hot, with an evident cleansing faculty; they have in the chewing a certain clammy and gluing quality.", "gloss": "The leaves and bark of the elm are moderately hot, cleansing, and clammy in the chewing.", "locator": "Book III, Chap. 116 'Of the Elm Tree', The Temperature and Virtues", "not_counted_why": "Gerard's elm is the European Ulmus, not the American slippery elm. Shown, not counted.", "note": "Gerard's elm is the European Ulmus, not the American slippery elm. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Also the European elm, so it is shown and not counted. Note that Culpeper contradicts himself: his catalogue entry 'Ulmi. Of Elm. Moderately hot and cleansing' (offset ~836512) makes the same tree hot.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "THE ELM TREE. ... Government and virtues. It is a cold and saturnine plant.", "gloss": "The elm is a cold plant.", "locator": "ELM TREE chapter (Gutenberg #49513, offset ~261563)", "not_counted_why": "Also the European elm, so it is shown and not counted. Note that Culpeper contradicts himself: his catalogue entry 'Ulmi. Of Elm. Moderately hot and cleansing' (offset ~836512) makes the same tree hot.", "note": "Also the European elm, so it is shown and not counted. Note that Culpeper contradicts himself: his catalogue entry 'Ulmi. Of Elm. Moderately hot and cleansing' (offset ~836512) makes the same tree hot.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Neutral"}}}$j$::jsonb);

-- H058 St. John's Wort (3 sources, SOURCES DISAGREE)
insert into _energetics_batch5 values ('H058', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787) and Rafinesque, Medical Flora (1828-30): Hypericum is treated as a resolvent and vulnerary, with no temperature or moisture", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Hypericum perforatum entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the flower and the leaf; all three English writers give the degree for the herb."], "part_used": "Flower, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Hypericon. St. John's Wort. It is as gallant a wound-herb as any is, either given inwardly, or outwardly applied to the wound: it is hot and dry, opens stoppings, helps spitting and vomiting of blood, it cleanses the reins, provokes the menses", "gloss": "St. John's wort is hot and dry.", "locator": "Catalogue of simples, Herbs, 'Hypericon' (Gutenberg #49513, offset ~872905)", "not_counted_why": "", "note": "No authority is named, so this is Culpeper's own. He gives no degree here, and his tables list St. John's-wort only among the herbs that heat the joints.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VI. The Qualities. Vt is hot and dry in the firft degree, thin, and of fubtil parts, Anodyn, Digeftive, Aperitive, Abfterfive, Diuretick, Difcnffive, Trau- matick or Vulnerary", "gloss": "St. John's wort is hot and dry in the first degree.", "locator": "Chapter 'Of JOHNSWORT Great Common, OR, HYPERICON', The Qualities (OCR at offset 3185971; the chapter number on the page is not legible)", "not_counted_why": "", "note": "Salmon's chapter is the true Hypericon of Dioscorides, the common great St. John's wort, which is this plant. His Tutsan chapter, a different species, is separate.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Gerard names Galen inside the sentence, so it is a report and is not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "St. John's Wort (as Galen teacheth) is hot and dry, being of substance thin.", "gloss": "St. John's wort is hot and dry, of thin substance.", "locator": "Book II, Chap. 158 'Of St. John's Wort', The Temperature", "not_counted_why": "Gerard names Galen inside the sentence, so it is a report and is not counted.", "note": "Gerard names Galen inside the sentence, so it is a report and is not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H059 Thyme (3 sources, sources agree)
insert into _energetics_batch5 values ('H059', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Thymus vulgaris entry found", "Schopf 1787 and Rafinesque 1828-30: no thyme entry"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the leaf and the flower; the old books give the degree for the herb."], "part_used": "Leaf, Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Temperature. These kinds of Thyme are hot and dry in the third degree.", "gloss": "The garden thymes are hot and dry in the third degree.", "locator": "Book II, Chap. 174 'Of Garden Thyme', The Temperature", "not_counted_why": "", "note": "The kinds of the chapter are named in its description: 'our common garden Thyme', which is Thymus vulgaris, and the broad-leaved thyme. Wild thyme has its own chapter, so this is not a statement about thyme as a group.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Thymum. Thyme. Hot and dry in the third degree; helps coughs and shortness of breath, provokes the menses, brings away dead children and the after birth; purges flegm, cleanses the breast and lungs, reins and matrix; and in his degree tables, Time is listed hot in the third degree and dry in the third degree", "gloss": "Thyme is hot and dry in the third degree.", "locator": "Catalogue of simples, Herbs, 'Thymum' (Gutenberg #49513, offset ~897310); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "No authority is named. Culpeper lists Mother of Time, the wild thyme, separately in the same tables.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "XI. The Qualities. They are hot and dry in the third Degree at leaft; Aperitive, Abfterfive, Aftringent, Diuretick, Stomatick, Cephalick, Neu- rotick, Hyfterick, Nephritick, Alexipharmick, and Emmenagogick.", "gloss": "The garden thymes are hot and dry in the third degree at least.", "locator": "Chap. DCXCVII 'Of THYME Garden', The Qualities (OCR at offset 6040206)", "not_counted_why": "", "note": "His five kinds are all garden thymes, the first being 'our Common Garden Thyme'. Wild thyme is his next chapter and simply refers back to this one.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H060 Turmeric (4 sources, sources agree)
insert into _energetics_batch5 values ('H060', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Bhavaprakasha 199, 'the mango-scented haridra is cold': that is Curcuma amada, a different species", "Dutt, Materia Medica of the Hindus (1877) and Dymock, Pharmacographia Indica: turmeric is described at length by use, with no degree of heat or dryness of their own", "Culpeper 1653: Turmerick appears only in his list of roots that heat the liver, with no degree; Gerard 1633 and Salmon 1710: no turmeric chapter in the parts read"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Bhavaprakasha (16th c.)"}], "temperature": [{"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the rhizome, which is the part every source below is talking about."], "part_used": "Rhizome", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "हरिद्रा कटुका तिक्ता रूक्षोष्णा कफपित्तनुत् । वर्ण्या त्वग्दोषमेहास्रशोथपाण्डुव्रणापहा ॥", "gloss": "haridra katuka tikta ruksha-ushna: turmeric is pungent, bitter, DRY and HOT, and conquers phlegm and bile; it improves the complexion and removes skin disease, urinary disease, blood disorder, swelling, pallor and wounds.", "locator": "Haritakyadi varga 197", "not_counted_why": "", "note": "ruksha is the dry word and ushna is the hot word, and both describe the drug itself.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "haridřā kaṭutiktoṣṇā kaphavātāsrakuṣṭhanut / mehakaṇḍūvraṇān hanti dehavarṇavidhāyinī //", "gloss": "haridra katu-tikta-ushna: turmeric is pungent, bitter and HOT, conquers phlegm, wind, blood disorder and leprosy, destroys urinary disease, itching and wounds, and gives the body its colour.", "locator": "Rajanighantu 5.199", "not_counted_why": "", "note": "Temperature only; no moisture word.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "薑黃 瀉、破血行氣。味苦辛溫。色黃入脾。兼入肝經。", "gloss": "Jiang huang: it drains, breaks blood stasis and moves the qi. Taste bitter and pungent, WARM. Yellow in colour, it enters the spleen and also the liver channel.", "locator": "卷二 草部, 薑黃 (congxin.txt offset 25933)", "not_counted_why": "", "note": "Wu Yiluo's own reading. Jiang huang is Curcuma longa, the stored plant. Temperature only.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. The article is marked as new in the Tang Materia Medica of 659, so the heading is copied from a book that was not read, and the contradicting 'hot' is Chen Cangqi quoted. Neither is Li Shizhen's own reading, and his own discussion gives no degree. Shown, not counted, and note that the entry carries two opposite readings.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "根氣味辛苦大寒無毒{{SKnotes|藏器曰辛少苦多性熱不冷云大寒誤矣}}", "gloss": "Root, qi and flavour: pungent, bitter, GREATLY COLD, not toxic. Chen Cangqi adds: little pungency and much bitterness, its nature is HOT and not cold; to call it greatly cold is an error.", "locator": "卷十四 草之三 芳草類, 薑黃, 根氣味 (bcgm_14.txt offset 39402)", "not_counted_why": "The article is marked as new in the Tang Materia Medica of 659, so the heading is copied from a book that was not read, and the contradicting 'hot' is Chen Cangqi quoted. Neither is Li Shizhen's own reading, and his own discussion gives no degree. Shown, not counted, and note that the entry carries two opposite readings.", "note": "The article is marked as new in the Tang Materia Medica of 659, so the heading is copied from a book that was not read, and the contradicting 'hot' is Chen Cangqi quoted. Neither is Li Shizhen's own reading, and his own discussion gives no degree. Shown, not counted, and note that the entry carries two opposite readings.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H061 Usnea (3 sources, shown, none counted)
insert into _energetics_batch5 values ('H061', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Rafinesque, Medical Flora (1828-30), under LICHEN: 'L. plicatus and other sp. of G. Usnea or Beardmoss, are astringent, once used for hemorrhage, hernia and epilepsy', which is a virtue and not a temperature", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Schopf 1787: no Usnea entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books speak of tree moss as a group and say its quality changes with the tree it grows on, and the one writer who names Usnea is passing on Galen.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because readings were found but none of them counts: No pre-1900 source found for this exact plant. The old books speak of tree moss as a group and say its quality changes with the tree it grows on, and the one writer who names Usnea is passing on Galen.", "The stored organism is the lichen Usnea barbata and the stored part is the whole thallus."], "part_used": "Thallus (whole lichen)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. A statement about the tree mosses as a group, and expressly one that changes with the tree, so it does not settle on a reading for this lichen. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature. Moss is somewhat cold and binding, which notwithstanding is more and less according unto the nature and faculty of that tree on which it groweth, and especially of his bark: for it taketh unto itself and also retaineth a certain property of that bark", "gloss": "Moss is somewhat cold and binding, more or less according to the tree it grows on.", "locator": "Book III, Chap. 161 'Of Moss of trees', The Temperature", "not_counted_why": "A statement about the tree mosses as a group, and expressly one that changes with the tree, so it does not settle on a reading for this lichen. Shown, not counted.", "note": "A statement about the tree mosses as a group, and expressly one that changes with the tree, so it does not settle on a reading for this lichen. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The same group statement about moss, with the same caveat about the tree. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Muscus. Mosse. Is something cold and binding, yet usually retains a smatch of the property of the tree it grows on; therefore that which grows upon oaks is very dry and binding. Serapio saith that it being infused in wine, and the wine drank, it stays vomiting and fluxes", "gloss": "Moss is something cold and binding, and keeps something of the tree it grows on.", "locator": "Catalogue of simples, Herbs, 'Muscus' (Gutenberg #49513, offset ~882275)", "not_counted_why": "The same group statement about moss, with the same caveat about the tree. Shown, not counted.", "note": "The same group statement about moss, with the same caveat about the tree. Shown, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. This is the closest any old book comes to naming the drug, because Salmon expressly says the apothecaries call tree moss Usnea. It is still not counted: the reading is given 'as Galen says', and it is a statement about the tree mosses as a group whose quality he says changes with the tree.", "assigns_moisture": "Dry", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "IX. The Qualities. They are temperate in re- fpect to heat or cold, of a Drying and Digeftive quality withall, as Galen fays, efpecially that which grows upon the great Cedar.", "gloss": "The tree mosses are temperate as to heat and cold, and drying, as Galen says, especially the one growing on the cedar.", "locator": "Chap. CCCCXCIX 'Of MOSS Tree' (OCR at offset 3982876; the chapter opens at offset 3976612 and its Names section says 'By the Apothecaries it is called Usnea')", "not_counted_why": "This is the closest any old book comes to naming the drug, because Salmon expressly says the apothecaries call tree moss Usnea. It is still not counted: the reading is given 'as Galen says', and it is a statement about the tree mosses as a group whose quality he says changes with the tree.", "note": "This is the closest any old book comes to naming the drug, because Salmon expressly says the apothecaries call tree moss Usnea. It is still not counted: the reading is given 'as Galen says', and it is a statement about the tree mosses as a group whose quality he says changes with the tree.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H062 Uva Ursi (1 source, shown, none counted)
insert into _energetics_batch5 values ('H062', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787), no. 146 ARBVTVS Vva Vrsi: 'QVAL. styptica, inodora, tinctoria ... vis: adstringens, coriaria, obstipans, diuretica', which is astringency and virtue, never a temperature or a moisture", "Rafinesque, Medical Flora (1828-30), no. 9 ARBUTUS UVA-URSI: astringent and diuretic properties, no temperature or moisture", "Culpeper 1653 and Salmon 1710: no bearberry chapter", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no bearberry entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant and part. The one old reading is about the whortleberries as a group, and it describes their berries rather than the bearberry leaf.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this exact plant and part. The one old reading is about the whortleberries as a group, and it describes their berries rather than the bearberry leaf.", "The stored plant is Arctostaphylos uva-ursi and the stored part is the leaf."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Three reasons not to count it. The sentence is about the whortleberries as a group; the group is Vaccinium, not Arctostaphylos, even though Uva ursi is mentioned in the chapter; and the reading is for the berries, while the stored part is the leaf.", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature. These Vaccinia or Whortleberries are cold even in the latter end of the second degree and dry also, with a manifest astriction or binding quality. Red Whortleberries are cold and dry, and also binding.", "gloss": "The whortleberries are cold in the latter end of the second degree and dry.", "locator": "Book III, Chap. 73 'Of Worts or Whortleberries', The Temperature (the same chapter notes that 'Lobel setteth forth another of the Whortleberries, under the title of Uva ursi')", "not_counted_why": "Three reasons not to count it. The sentence is about the whortleberries as a group; the group is Vaccinium, not Arctostaphylos, even though Uva ursi is mentioned in the chapter; and the reading is for the berries, while the stored part is the leaf.", "note": "Three reasons not to count it. The sentence is about the whortleberries as a group; the group is Vaccinium, not Arctostaphylos, even though Uva ursi is mentioned in the chapter; and the reading is for the berries, while the stored part is the leaf.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H063 Valerian (2 sources, sources agree)
insert into _energetics_batch5 values ('H063', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Salmon 1710, Chap. DCCXIX 'Of VALERIAN Garden: OR, SETWALL': the Qualities section is destroyed in the archive.org scan. The page is printed in two columns and they have interleaved, so the text reads 'XII. The Qualities. As the Roots ate' and then jumps into the middle of another section's Virtues. Reported as damaged; nothing has been reconstructed", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Valeriana officinalis entry found", "Rafinesque, Medical Flora (1828-30): Valeriana officinalis is named as an antispasmodic, with no temperature or moisture"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root, which is the part Culpeper's table and Gerard's sentence are both about."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Roots hot in the first degree. ... wild Parsnips, Parsley, Valerian, great and small, Knee-holly, Satyrion, Scorzonera, Skirrets.; and in the same tables, 'Bowels. Valerian great and small.'", "gloss": "Valerian, great and small, is listed among the roots hot in the first degree.", "locator": "Culpeper's degree tables, 'Roots' (Gutenberg #49513, offset ~935400)", "not_counted_why": "", "note": "Culpeper's catalogue entry reads 'Valeriana. Valerian, or Setwall. See the roots', which sends the reader to this table. The greater Valerian is Valeriana officinalis. His dry and moist root tables list only 'Bazil, Valerian and Spatling Poppy', which is the other plant his tables call Bazil Valerian, so this is a temperature only.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Gerard names Dioscorides inside the sentence, which by your rule makes it a report, and he then adds his own test by taste and smell. I have not counted it, and I have raised the shape of the sentence as a question, because it is the same shape as the Salmon oats sentence flagged in batch 4.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The garden Valerian is hot, as Dioscorides saith, but not much, neither the green root, but the dried ones; for the green is easily perceived to have very little heat, and the dried to be hotter, which is found by the taste and smell.", "gloss": "Garden valerian is hot, but not much; the green root has very little heat and the dried root is hotter.", "locator": "Book II, Chap. 440 'Of Valerian, or Setwall', The Temperature", "not_counted_why": "Gerard names Dioscorides inside the sentence, which by your rule makes it a report, and he then adds his own test by taste and smell. I have not counted it, and I have raised the shape of the sentence as a question, because it is the same shape as the Salmon oats sentence flagged in batch 4.", "note": "Gerard names Dioscorides inside the sentence, which by your rule makes it a report, and he then adds his own test by taste and smell. I have not counted it, and I have raised the shape of the sentence as a question, because it is the same shape as the Salmon oats sentence flagged in batch 4.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

