insert into _energetics_batch5 values ('H066', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Bencao Congxin (1757), the shan yao entry in the vegetable section: taste sweet, entering lung and spleen, with no temperature word at all", "Rafinesque, Medical Flora (1828-30), DIOSCOREA: 'D. villosa or Wild Yam, used by the Western tribes, roots and meal. Leaves also edible', a food note with no quality", "Culpeper 1653, Gerard 1633, Salmon 1710: no Dioscorea villosa chapter (the plant is American)", "Bhavaprakasha, Rajanighantu, Dymock Vols. I-III, Schopf 1787: no Dioscorea villosa entry"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The one old reading describes the Chinese yam, a different species from the American wild yam this entry is about.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this exact plant. The one old reading describes the Chinese yam, a different species from the American wild yam this entry is about.", "The stored plant is the American Dioscorea villosa and the stored part is the root."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. The Chinese shu yu, now shan yao, is Dioscorea polystachya and its kin, not the American Dioscorea villosa. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "薯蘓 味甘，溫。主傷中，補虛羸，除寒熱邪氣，補中，益氣力，長肌肉。", "gloss": "Shu yu: taste sweet, nature WARM. For injury to the centre, it supplements weakness and wasting, drives out cold and hot evil qi, supplements the centre, benefits the strength and grows the flesh.", "locator": "草上品, 薯蘓 (Sun Xingyan recension, shennong_sun.txt offset 14783)", "not_counted_why": "The Chinese shu yu, now shan yao, is Dioscorea polystachya and its kin, not the American Dioscorea villosa. Shown, not counted.", "note": "The Chinese shu yu, now shan yao, is Dioscorea polystachya and its kin, not the American Dioscorea villosa. Shown, not counted.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

