insert into _energetics_batch5 values ('H068', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787) and Rafinesque 1828-30: no Betonica officinalis entry", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no betony entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what all three English writers mean by betony."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Betony is hot and dry in the second degree: it hath force to cut, as Galen saith.", "gloss": "Betony is hot and dry in the second degree.", "locator": "Book II, Chap. 244 'Of Betony', The Temperature", "not_counted_why": "", "note": "Galen is named, but only for the cutting faculty in the second half of the sentence. The degree is Gerard's own, so it counts.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Betonica vulgaris. Common or Wood Betony: hot and dry in the second degree, helps the falling sickness and all head-aches coming of cold, cleanses the breast and lungs, opens stoppings of the liver and spleen", "gloss": "Wood betony is hot and dry in the second degree.", "locator": "Catalogue of simples, Herbs, 'Betonica vulgaris' (Gutenberg #49513, offset ~848572)", "not_counted_why": "", "note": "The entry names the plant exactly and ends with dosing advice, not with an authority.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. Ihe Qualities. They are hot and dry in the fecond degree ; Abtterfive, Digeftive, Ditcuffive, In- carnative, and Vulnerary ; Cephalick, Neurotick, Stomatick, Cardiack, Hyfterick, Arthritick", "gloss": "The wood betonies are hot and dry in the second degree.", "locator": "Chap. LXV 'Of BETONY Wood', The Qualities (OCR at offset 619658; the chapter opens at offset 617150)", "not_counted_why": "", "note": "His two kinds are the purple and the white flowered wood betony, which he says 'differ nothing one from another but in the colour of the Flowers', so the sentence names two kinds of the same plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H069 Yarrow (3 sources, SOURCES DISAGREE)
insert into _energetics_batch5 values ('H069', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787) and Rafinesque 1828-30: Achillea is described by virtue only", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Achillea millefolium entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Culpeper (1653) and Salmon (1710) read it as cold. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the flower and the leaf; the old books give the degree for the herb."], "part_used": "Flower, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source cool, app warm).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Millefolium. Yarrow. Meanly cold and binding, an healing herb for wounds, stanches bleeding; and some say the juice snuffed up the nose, causeth it to bleed, whence it was called, Nose-bleed; it stops lasks, and the menses. Galen.; and in his degree tables, 'Herbs cold in the first degree. ... Yarrow'", "gloss": "Yarrow is meanly cold and binding, and by his table cold in the first degree.", "locator": "Catalogue of simples, Herbs, 'Millefolium' (Gutenberg #49513, offset ~881921); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The entry ends with the authority 'Galen' in italics, which by your confirmed rule is Culpeper's reference and not a report, so it counts. Binding is a virtue and not a moisture, and Yarrow appears in none of his dry tables, so this is a temperature only.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source cool, app warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "X. The Qualities. They are cold in the firft degree, and dry in the end of the fecond, or begin- ning of the third, Aftringent, Glutinative, Anodyn, and Vulnerary.", "gloss": "The yarrows are cold in the first degree and dry at the end of the second or beginning of the third.", "locator": "Chap. DCCL 'Of YARROW Land, or Milfoil', The Qualities (OCR at offset 6746139; the chapter opens at offset 6740867)", "not_counted_why": "", "note": "His first and commonest kind is the common yarrow, Achillea millefolium, the stored plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Gerard names Galen inside the sentence, so it is a report and is not counted. His next chapter, 439 'Of Yellow Yarrow, or Milfoil', is a different species.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Yarrow, as Galen saith, is not unlike in temperature to the Sideritides, or Ironworts, that is to say, cleansing, and meanly cold, but it most of all bindeth.", "gloss": "Yarrow is meanly cold and binding, like the ironworts.", "locator": "Book II, Chap. 438 'Of Yarrow, or Nose-Bleed', The Temperature", "not_counted_why": "Gerard names Galen inside the sentence, so it is a report and is not counted. His next chapter, 439 'Of Yellow Yarrow, or Milfoil', is a different species.", "note": "Gerard names Galen inside the sentence, so it is a report and is not counted. His next chapter, 439 'Of Yellow Yarrow, or Milfoil', is a different species.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H070 Yellow Dock (3 sources, shown, none counted)
insert into _energetics_batch5 values ('H070', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Culpeper 1653: his catalogue lists 'Sharp-pointed-Dock' among the SEEDS but gives it no degree there", "Rafinesque, Medical Flora (1828-30): Rumex is named among the alteratives and for cancer, with no temperature or moisture", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Rumex crispus entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books speak of the docks as a group, or name kinds that are not the curled dock this entry is about.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because readings were found but none of them counts: No pre-1900 source found for this exact plant. The old books speak of the docks as a group, or name kinds that are not the curled dock this entry is about.", "The stored plant is Rumex crispus, the curled dock, and the stored part is the root."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. The sentence opens with the word 'Generally' and covers all the docks together, which is a group statement. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature Generally all the Docks are cold, some little and moderately, and some more: they do all of them dry, but not all after one manner: notwithstanding some are of opinion that they are dry almost in the third degree.", "gloss": "Generally all the docks are cold and all of them dry, though not all in the same manner.", "locator": "Book II, Chap. 81 'Of Docks', The Temperature", "not_counted_why": "The sentence opens with the word 'Generally' and covers all the docks together, which is a group statement. Shown, not counted.", "note": "The sentence opens with the word 'Generally' and covers all the docks together, which is a group statement. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. 'All the ordinary sort of Docks' is a group statement. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Rumex. Dock; All the ordinary sort of Docks are of a cool and drying substance, and therefore stop fluxes; and the leaves are seldom used in physic.", "gloss": "All the ordinary sort of docks are cool and drying.", "locator": "Catalogue of simples, Herbs, 'Rumex' (Gutenberg #49513, offset ~890603)", "not_counted_why": "'All the ordinary sort of Docks' is a group statement. Shown, not counted.", "note": "'All the ordinary sort of Docks' is a group statement. Shown, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Salmon names his docks and none of them is the curled dock. Chap. 220 is Lapathum sylvestre vulgare, the broad-leaved dock, and Chap. 221 is Rumex acutus, the sharp-pointed dock. Shown, not counted, on the species rule.", "assigns_moisture": "Dry", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "VI. The Qualities. It is temperate in refpect to Heat or Coldnefs, and dry in the fecond Degree, more efpecially the Seed, which is very Aftringent.", "gloss": "The common dock is temperate as to heat and cold and dry in the second degree.", "locator": "Chap. CCXX 'Of DOCK Common', The Qualities (OCR at offset 1757334); Chap. CCXXI 'Of DOCK Sharp-pointed' says its 'Qualities, Specification, Preparations and Virtues, are the same with those of the Common Dock declared in Chap. 220'", "not_counted_why": "Salmon names his docks and none of them is the curled dock. Chap. 220 is Lapathum sylvestre vulgare, the broad-leaved dock, and Chap. 221 is Rumex acutus, the sharp-pointed dock. Shown, not counted, on the species rule.", "note": "Salmon names his docks and none of them is the curled dock. Chap. 220 is Lapathum sylvestre vulgare, the broad-leaved dock, and Chap. 221 is Rumex acutus, the sharp-pointed dock. Shown, not counted, on the species rule.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

