-- H072 Agrimony (3 sources, SOURCES DISAGREE)
insert into _energetics_batch5 values ('H072', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 5, "checked_no_reading": ["Schopf, Materia Medica Americana (1787) and Rafinesque 1828-30: Agrimonia eupatoria is listed among the mild astringents with no temperature or moisture", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Agrimonia eupatoria entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633), Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what all three English writers mean by agrimony."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Temperature. It is hot, and doth moderately bind, and is of a temperate dryness. Galen saith that Agrimony is of fine and subtle parts, that it cutteth and scoureth", "gloss": "Agrimony is hot, moderately binding, and of a temperate dryness.", "locator": "Book II, Chap. 242 'Of Agrimony', The Temperature", "not_counted_why": "", "note": "Galen is named only for the second sentence, about fine parts and scouring. The first sentence is Gerard's own. 'A temperate dryness' is read here as a moderate dryness rather than as the Galenic 'temperate', because the word temperate qualifies the dryness and does not stand alone.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Agrimonia. Agrimony. Galen's Eupatorium. It is hot and dry in the first degree, binding, it amends the infirmities of the liver, helps such as evacuate blood instead of water, helps inward wounds, opens obstructions. Galen, Pliny, Dioscorides, Serapio.; and in his degree tables, 'Intemperate and hot in the first degree, are Agrimony' and 'Herbs dry in the first degree. Agrimony'", "gloss": "Agrimony is hot and dry in the first degree.", "locator": "Catalogue of simples, Herbs, 'Agrimonia' (Gutenberg #49513, offset ~840229); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The authorities stand at the END of the entry, so by your confirmed rule they are Culpeper's references and the entry counts. His tables agree with it.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. They are all of them hot and dry in the firft Degree, but the Aromatick fomething hotter. They are Difcuffive, Aperitive, ing, a little Aftringent, Traumatick or Vulne- rary, and Strengthening", "gloss": "The agrimonies are all hot and dry in the first degree, the aromatic one somewhat hotter.", "locator": "Chap. IV 'Of AGRIMONY', The Qualities (OCR at offset 164492; the chapter opens at offset 160600)", "not_counted_why": "", "note": "The kinds are named in his own Kinds paragraph, the first being 'The Common Agrimony', which is the stored plant, so this is a sentence naming kinds and not a group statement.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H073 Aloe Vera (4 sources, sources agree)
insert into _energetics_batch5 values ('H073', $j${"agreement_state": "agree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Culpeper 1653, TEARS, LIQUORS, AND ROZINS, 'Aloes': a full entry on its purging, its effect on the senses and the liver, and his own dislike of it taken raw, but no temperature and no moisture; his degree table of concrete juices lists Aloes only among the things that purge choler gently", "Dymock, Pharmacographia Indica Vol. III (1893), Aloe vera: 'The juice is considered to be cathartic, cold, and useful for removing disease of the spleen', which reports the Sanskrit writers rather than giving his own reading, and his summary of the Mahometan physicians lists aperient, deobstruent, depurative, anthelmintic and tonic, with no degree", "Salmon 1710: no aloe chapter in Lib. I, the English herbs", "Bencao Congxin (1757) and Shennong Bencao Jing: no aloes entry found"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Cool", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Cool", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["On moisture, no counted source gives a reading at all. The only old moisture word for this plant is Gerard's 'dry in the third', and that sentence is about the juice sold in the shops, so it is shown above and set aside under the trade-good rule. The stored Moist therefore stands on the modern reading alone, with nothing counted either behind it or against it. Read the App value, moisture line at the foot of this page with that in mind: its 'no pre-1900 source found' is the builder's standard wording for an axis with no COUNTED reading, and here one uncounted reading was in fact found, namely Gerard's.", "On temperature, the two counted readings are the two Sanskrit ones, and both are cold, which is the way the stored value already reads.", "The stored parts are the leaf gel and the leaf latex. The old European and Arabic drug called aloes is the dried leaf latex, which is one of the two stored parts; the Sanskrit verses describe the plant itself."], "part_used": "Leaf Gel, Leaf Latex", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "कुमारी गृहकन्या च कन्या घृतकुमारिका । कुमारी भेदनी शीता तिक्ता नेत्र्या रसायनी । मधुरा बृंहणी बल्या वृष्या वातविषप्रणुत् ॥", "gloss": "kumari bhedani shita tikta: aloe is purgative, COLD, bitter, good for the eyes, a rasayana, sweet, nourishing, strengthening, and conquers wind and poison.", "locator": "Guduchyadi varga 229-230", "not_counted_why": "", "note": "Kumari, also ghrita-kumari, is Aloe vera; Dymock's Pharmacographia Indica gives exactly these Sanskrit synonyms under Aloe vera, Linn. Temperature only: brimhani, nourishing, is not one of the moisture words.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "gṛhakanyā kumārī ca kanyakā dīrghapattrikā ... gṛhakanyā himā tiktā madagandhiḥ kaphāpahā / pittakāsaviṣaśvāsakuṣṭhaghnī ca rasāyanī //", "gloss": "grihakanya hima tikta: aloe is COLD, bitter, smelling of must, removes phlegm, and destroys bile, cough, poison, asthma and skin disease; it is a rasayana.", "locator": "Rajanighantu 4.47-49", "not_counted_why": "", "note": "Temperature only; no moisture word.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. Set aside under the trade-good rule, by your ruling of 15 September 2026. His chapter and his names really are this plant: the Names section gives the Spanish 'Azevar' and 'Yerba bavosa', which are Aloe vera and nothing else, and that is worth showing. But the sentence that carries the degree says 'Aloe, that is to say, the juice which is used in physic', and that is the drug sold in the shops, which several plants make. A chapter about the right plant does not turn a sentence about the shop drug into a reading of the plant.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Temperature. Aloe, that is to say, the juice which is used in physic, is good for many things. It is hot, and that in the first or second degree, but dry in the third, extreme bitter, yet without biting.", "gloss": "The aloe juice used in physic is hot in the first or second degree and dry in the third.", "locator": "Book II, Chap. 141 'Of Herb Aloe or Sea Houseleek', The Temperature", "not_counted_why": "Set aside under the trade-good rule, by your ruling of 15 September 2026. His chapter and his names really are this plant: the Names section gives the Spanish 'Azevar' and 'Yerba bavosa', which are Aloe vera and nothing else, and that is worth showing. But the sentence that carries the degree says 'Aloe, that is to say, the juice which is used in physic', and that is the drug sold in the shops, which several plants make. A chapter about the right plant does not turn a sentence about the shop drug into a reading of the plant.", "note": "Set aside under the trade-good rule, by your ruling of 15 September 2026. His chapter and his names really are this plant: the Names section gives the Spanish 'Azevar' and 'Yerba bavosa', which are Aloe vera and nothing else, and that is worth showing. But the sentence that carries the degree says 'Aloe, that is to say, the juice which is used in physic', and that is the drug sold in the shops, which several plants make. A chapter about the right plant does not turn a sentence about the shop drug into a reading of the plant.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Set aside under the trade-good rule. The reading is marked as quoted from the Kaibao Bencao of 973, and the entry describes an imported drug whose plant nobody in it can pin down: Li Xun calls it a tree resin from Persia and Li Shizhen records a second account calling it a herb. No species is named.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味苦寒無毒主治熱風煩悶胸膤間熱氣明目鎮心{{SKnotes|開寶}}", "gloss": "Lu hui: bitter, COLD, not toxic. For hot wind with vexation and heat in the chest and diaphragm; it brightens the eyes and quiets the heart.", "locator": "卷三十四 木之一, 盧㉑ (bcgm_34.txt offset 48200; the Siku Quanshu text writes the name with the characters lu hui in an older form)", "not_counted_why": "Set aside under the trade-good rule. The reading is marked as quoted from the Kaibao Bencao of 973, and the entry describes an imported drug whose plant nobody in it can pin down: Li Xun calls it a tree resin from Persia and Li Shizhen records a second account calling it a herb. No species is named.", "note": "Set aside under the trade-good rule. The reading is marked as quoted from the Kaibao Bencao of 973, and the entry describes an imported drug whose plant nobody in it can pin down: Li Xun calls it a tree resin from Persia and Li Shizhen records a second account calling it a herb. No species is named.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

