insert into _energetics_batch5 values ('H074', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 5, "checked_no_reading": ["Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing: the Chinese dang gui is Angelica sinensis and bai zhi is Angelica dahurica, different species", "Bhavaprakasha, Rajanighantu, Dymock Vols. I-III: no Angelica archangelica entry with a thermal quality", "Schopf 1787 and Rafinesque 1828-30: the American Angelica entries are other species"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the root, the seed and the leaf; all three English writers give the degree for the garden angelica as a whole."], "part_used": "Root, Seed, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Temperature. Angelica, especially that of the garden, is hot and dry in the third degree; therefore it openeth, attenuateth or maketh thin, digesteth, and procureth sweat.", "gloss": "Garden angelica is hot and dry in the third degree.", "locator": "Book II, Chap. 387 'Of Angelica', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Angelica. Is hot and dry in the third degree; opens, digests, makes thin, strengthens the heart, helps fluxes, and loathsomeness of meat. It is an enemy to poison and pestilence, provokes menses, and brings away the placanta.; and in his degree tables Angelica is listed hot in the third degree and dry in the third degree, among both the herbs and the roots", "gloss": "Angelica is hot and dry in the third degree.", "locator": "Catalogue of simples, Herbs, 'Angelica' (Gutenberg #49513, offset ~843433); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000); Culpeper's degree tables, 'Roots' (Gutenberg #49513, offset ~935400)", "not_counted_why": "", "note": "No authority is named. His herb and root tables agree with the entry.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. Avis hot and dry inthe fecond degree; but Schroder faith in the third degree, which T believe not. It opens, incides, attermates or makes thin, Digefts, Difeuffes, and is Sudorifick.", "gloss": "Garden angelica is hot and dry in the second degree; Schroder says the third, which Salmon does not believe.", "locator": "Chap. XV 'Of Garden ANGELICA', The Qualities (OCR at offset 264000; the chapter opens at offset 262316)", "not_counted_why": "", "note": "Salmon names Schroder only to reject him and gives his own degree, so this is first-hand.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H075 Anise Hyssop (1 source, shown, none counted)
insert into _energetics_batch5 values ('H075', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; no pre-1900 source found)"}, "batch": 5, "checked_no_reading": ["Culpeper 1653, Gerard 1633, Salmon 1710: no Agastache chapter (the plant is North American)", "Schopf, Materia Medica Americana (1787) and Rafinesque, Medical Flora (1828-30): no Agastache foeniculum entry", "Bencao Gangmu, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no entry for this species"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The one old reading describes the Asian huo xiang, a different species from the North American anise hyssop this entry is about.", "no_pre1900_source_found": false, "notes": ["Proposed line for the page, because a reading was found but it does not count: No pre-1900 source found for this exact plant. The one old reading describes the Asian huo xiang, a different species from the North American anise hyssop this entry is about.", "The stored plant is the North American Agastache foeniculum and the stored part is the aerial herb."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Huo xiang is Pogostemon cablin and Agastache rugosa, the Korean mint, which is why Wu Yiluo says it comes from the far south. The stored plant is Agastache foeniculum, the North American anise hyssop. Shown, not counted, on the species rule. The herb record's own notes field already says the plant is related to Agastache rugosa.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "霍香 宣、去惡氣。辛甘微溫。入手足太陰。快氣和中。開胃止呕。 ... 出交廣。", "gloss": "Huo xiang: it diffuses and drives off foul air. Pungent, sweet, SLIGHTLY WARM. It enters the hand and foot taiyin, quickens the qi and harmonises the centre, opens the appetite and stops vomiting. It comes from Jiaozhou and Guangzhou.", "locator": "卷二 草部, 霍香 (congxin.txt offset 30566)", "not_counted_why": "Huo xiang is Pogostemon cablin and Agastache rugosa, the Korean mint, which is why Wu Yiluo says it comes from the far south. The stored plant is Agastache foeniculum, the North American anise hyssop. Shown, not counted, on the species rule. The herb record's own notes field already says the plant is related to Agastache rugosa.", "note": "Huo xiang is Pogostemon cablin and Agastache rugosa, the Korean mint, which is why Wu Yiluo says it comes from the far south. The stored plant is Agastache foeniculum, the North American anise hyssop. Shown, not counted, on the species rule. The herb record's own notes field already says the plant is related to Agastache rugosa.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

do $do$
declare
  rec record;
  n int;
  written int := 0;
  skipped int := 0;
begin
  for rec in select herb_id, citation from _energetics_batch5 order by herb_id loop
    update public.herbs h
       set energetics_citation = rec.citation,
           last_updated = now()
     where h.herb_id = rec.herb_id
       and h.energetics_citation is distinct from rec.citation
       and (h.energetics_citation is null or h.energetics_citation ? 'batch');
    get diagnostics n = row_count;
    if n = 1 then
      written := written + 1;
    else
      if exists (select 1 from public.herbs
                  where herb_id = rec.herb_id and energetics_citation = rec.citation) then
        skipped := skipped + 1;
      else
        raise exception '%.energetics_citation: live value is neither NULL nor a batch object (or the herb is missing); not overwritten', rec.herb_id;
      end if;
    end if;
  end loop;
  raise notice 'energetics batch 5: %s written, %s already current', written, skipped;
end
$do$;

-- -----------------------------------------------------------------------------
-- 2. Verification. Any failure aborts the whole transaction.
-- -----------------------------------------------------------------------------
do $do$
declare
  bad text[] := '{}';
  n int;
  moved text;
begin
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 5;
  if n <> 25 then bad := bad || ('batch 5 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs where energetics_citation ? 'batch';
  if n <> 125 then bad := bad || ('batch citations in total: ' || n || ', expected 125'); end if;
  select count(*) into n from public.herbs
   where energetics_citation is not null and not (energetics_citation ? 'batch');
  if n <> 69 then bad := bad || ('legacy single-source citations: ' || n || ', expected 69'); end if;

  -- Every batch herb has a sources array or the honest no-source flag, and every
  -- stored source carries the fields the page renders.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (jsonb_typeof(energetics_citation->'sources') = 'array'
          or (energetics_citation->>'no_pre1900_source_found')::boolean);
  if n <> 125 then bad := bad || ('batch herbs with a sources array or the no-source flag: ' || n || ', expected 125'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0
     and not (energetics_citation->>'no_pre1900_source_found')::boolean;
  if n <> 0 then bad := bad || (n || ' herb(s) have no source and no no-source flag'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch' and coalesce(energetics_citation->>'rule', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) carry no basis line'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch';
  if n <> 313 then bad := bad || ('stored sources: ' || n || ', expected 313'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s ? 'source' and s ? 'year' and s ? 'corpus' and s ? 'tier'
              and s ? 'assigns_temperature' and s ? 'assigns_moisture'
              and s ? 'excerpt' and s ? 'locator' and s ? 'url'
              and s ? 'agreement' and s ? 'counted');
  if n <> 0 then bad := bad || (n || ' source(s) are missing a required field'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s->>'counted')::boolean
     and coalesce(s->>'not_counted_why', '') = '';
  if n <> 0 then bad := bad || (n || ' uncounted source(s) do not say why they were not counted'); end if;

  -- Never claim agreement the data does not carry.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'agreement_state' = 'disagree'
     and coalesce(energetics_citation->>'disagreement_text', '') = '';
  if n <> 0 then bad := bad || (n || ' disagreeing herb(s) carry no disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and coalesce(energetics_citation->>'disagreement_text', '') <> '';
  if n <> 0 then bad := bad || (n || ' agreeing herb(s) also carry a disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0;
  if n <> 0 then bad := bad || (n || ' herb(s) claim agreement with no sources at all'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'disagreement_text' like '%' || chr(8212) || '%';
  if n <> 0 then bad := bad || (n || ' disagreement sentence(s) contain an em dash'); end if;

  -- Sources found but none counted: the herb must say why, and a herb that DID
  -- count a source must never carry that line.
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean);
  if n <> 19 then bad := bad || ('herbs with sources but none counted: ' || n || ', expected 19'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean)
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) counted no source and say nothing about why'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') <> ''
     and exists (select 1 from jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
                  where (s->>'counted')::boolean);
  if n <> 0 then bad := bad || (n || ' herb(s) claim no counted source while showing one'); end if;

  -- 3. This batch changes NO app value. Nothing may have moved.
  select count(*), string_agg(h.herb_id, ', ' order by h.herb_id) into n, moved
    from public.herbs h join _energetics_before_b5 b using (herb_id)
   where h.temperature is distinct from b.temperature
      or h.moisture is distinct from b.moisture;
  if n <> 0 then
    bad := bad || ('energetics moved on ' || n || ' herb(s): ' || coalesce(moved, 'none') || '; this batch must move none');
  end if;
  select count(*) into n from public.herbs;
  if n <> (select count(*) from _energetics_before_b5) then
    bad := bad || 'the herb count changed'::text;
  end if;
  select count(*) into n from public.herb_energetics_evidence_v;
  if n <> 125 then bad := bad || ('herb_energetics_evidence_v rows: ' || n || ', expected 125'); end if;

  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 5: checks failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

-- 4. The tier gate, proved by READING the view as anon rather than by reading its
--    definition. A blind check that returns nothing looks healthy, so this asserts
--    a NON-EMPTY free result and a NULL source list together.
do $do$
declare
  bad text[] := '{}';
  free_text text;
  src jsonb;
  seen int;
begin
  begin
    set local role anon;
  exception when insufficient_privilege then
    raise notice 'cannot SET ROLE anon here; the functional tier check was skipped';
    return;
  end;
  select count(*) into seen from public.herb_energetics_evidence_v;
  if seen <> 125 then bad := bad || ('anon sees ' || seen || ' evidence rows, expected 125'); end if;
  select disagreement_text, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H051';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the disagreement sentence on H051'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H051'::text;
  end if;
  select no_counted_source_line into free_text
    from public.herb_energetics_evidence_v where herb_id = 'H052';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the no-counted-source line on H052'::text;
  end if;
  if (select no_pre1900_source_found from public.herb_energetics_evidence_v
       where herb_id = 'H056') is not true then
    bad := bad || 'anon cannot read the no-source flag on H056'::text;
  end if;
  reset role;
  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 5: tier gate failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

commit;
